<?php namespace App\Livewire\Vendor; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Livewire\Attributes\Layout; use Livewire\Component; #[Layout('layouts.app')] class ManageStall extends Component { use AuthorizesRequests; public string $name = ''; public string $location = ''; public string $status = 'active'; public function mount(): void { $stall = auth()->user()->stall; abort_if(!$stall, 403); $this->authorize('view', $stall); $this->name = $stall->name; $this->location = $stall->location; $this->status = $stall->status; } public function updateStall(): void { $stall = auth()->user()->stall; $this->authorize('update', $stall); $validated = $this->validate(['name' => ['required', 'string', 'max:255'], 'location' => ['required', 'string', 'max:255'], 'status' => ['required', 'in:active,inactive']]); $stall->update($validated); session()->flash('status', 'Stall details updated successfully.'); } public function render() { return view('livewire.vendor.manage-stall'); } }